package com.cpf.batch.agent.internal; import com.cpf.batch.agent.AgentProperties; import java.nio.file.Path; import java.util.*; import java.util.concurrent.TimeUnit;
public final class ServiceManager { private final AgentProperties p;public ServiceManager(AgentProperties p){this.p=p;} public Result execute(String id,Action a)throws Exception{var s=service(id);List<String> cmd;if(System.getProperty("os.name").toLowerCase().contains("windows")){if(s.getWindowsStartScript()==null||s.getWindowsStartScript().isBlank())throw new IllegalStateException("Windows script missing");cmd=List.of("pwsh","-NoProfile","-ExecutionPolicy","Bypass","-File",Path.of(s.getWindowsStartScript()).toAbsolutePath().normalize().toString(),"-Action",a.name());}else{String unit=s.getSystemdUnit();if(unit==null||!unit.matches("[A-Za-z0-9@_.-]+\\.service"))throw new SecurityException("invalid unit");String verb=switch(a){case START->"start";case STOP->"stop";case RESTART->"restart";case STATUS->"is-active";};cmd=List.of("systemctl",verb,unit);}Process pr=new ProcessBuilder(cmd).redirectErrorStream(true).start();boolean done=pr.waitFor(60,TimeUnit.SECONDS);if(!done){pr.destroyForcibly();return new Result(false,-1,"TIMEOUT");}String out=new String(pr.getInputStream().readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);return new Result(pr.exitValue()==0,pr.exitValue(),com.cpf.batch.runtime.SensitiveTextSanitizer.sanitize(out));} private AgentProperties.ServiceDefinition service(String id){return p.getServices().values().stream().filter(x->id.equals(x.getServiceId())).findFirst().orElseThrow(()->new SecurityException("unknown service"));}public enum Action{START,STOP,RESTART,STATUS}public record Result(boolean success,int exitCode,String output){} }
